  1	# Continue with Google on cyrus.my: owner runbook
  2	
  3	Optional, default off. One Nxeon account either way (same email = same account, linked only on a Google-verified email).
  4	
  5	## 1. Google Cloud console (project `cyrus-511708`)
  6	**Clients > Create client: Web application, name `Cyrus oAuth`**
  7	| Field | Value |
  8	|---|---|
  9	| Authorized JavaScript origins | `https://cyrus.my` |
 10	| Authorized redirect URIs | `https://cyrus.my/api/auth/google/callback` (exactly this; no trailing slash, no www) |
 11	
 12	**Branding (OAuth consent screen)**
 13	| Field | Value |
 14	|---|---|
 15	| App name | `Cyrus` |
 16	| User support email | the Cyrus support mailbox |
 17	| Authorized domain | `cyrus.my` |
 18	| Application home page | `https://cyrus.my` |
 19	| Privacy policy | `https://cyrus.my/legal/privacy` |
 20	| Terms of service | `https://cyrus.my/legal/terms` |
 21	| Developer contact email | the owner mailbox |
 22	| Audience / user type | External, publishing status **In production** (Testing mode only lets listed test users in) |
 23	| Scopes | `openid`, `.../auth/userinfo.email`, `.../auth/userinfo.profile` (non-sensitive; no verification review) |
 24	
 25	## 2. Store the credentials (never paste the secret into chat or a shell history line)
 26	```bash
 27	read -rp 'Cyrus Google client id: ' CID; read -rsp 'Cyrus Google client secret (hidden): ' CSEC; echo
 28	cp -p /opt/nxeon/.env /opt/nxeon/.env.bak.$(date +%Y%m%d%H%M%S)
 29	sed -i '/^CYRUS_GOOGLE_CLIENT_ID=/d;/^CYRUS_GOOGLE_CLIENT_SECRET=/d;/^CYRUS_GOOGLE_LOGIN=/d' /opt/nxeon/.env
 30	printf 'CYRUS_GOOGLE_LOGIN=1\nCYRUS_GOOGLE_CLIENT_ID=%s\nCYRUS_GOOGLE_CLIENT_SECRET=%s\n' "$CID" "$CSEC" >> /opt/nxeon/.env
 31	unset CID CSEC; chmod 600 /opt/nxeon/.env
 32	```
 33	Then restart `nxeon-web` (after the branch is deployed). Requires `CYRUS_DOMAIN_MODE=1` (already part of the cyrus.my launch). To roll back: delete `CYRUS_GOOGLE_LOGIN=1` and restart; the button disappears and the routes answer with the fixed "not available" error.
 34	
 35	## 3. nginx / Cloudflare
 36	`api/auth/google` must be in the app-path location regex of the cyrus.my server block (see CYRUS-MY-LAUNCH step 5) and `/api/*` is already a Cloudflare cache bypass.
 37	
 38	## 4. Check
 39	`https://cyrus.my/sign-in` shows "Continue with Google"; the consent screen reads "Cyrus"; after consent you land in the studio (or the private-beta panel if the account is not on the list).
 40	// "Continue with Google" on cyrus.my (CYRUS_GOOGLE_LOGIN). The protocol decisions only: no cookies, no Next, no
 41	// session writes, so tests drive it with fakes. The route handlers (app/cyrus-host/auth/google[/callback]) do the I/O.
 42	//
 43	//   start    : state + nonce + PKCE verifier + validated `next` -> one sealed, short-lived, host-only cookie; the
 44	//              browser goes to Google's consent screen with the Cyrus client.
 45	//   callback : cookie (consumed) <-> state, Google code -> token (PKCE + nonce) -> userinfo -> the SAME Nxeon account
 46	//              as Google login on nxeon.cloud (lib/google-account) -> Cyrus-host session (createCyrusSession, the
 47	//              handoff's own minting path, no Nxeon parent session) -> private-beta rule -> `next`.
 48	import { randomToken, safeEqual, seal, unseal } from "@/lib/cyrus/bridge/assertion";
 49	import { bridgeConfig, type BridgeConfig } from "@/lib/cyrus/bridge/config";
 50	import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
 51	import type { GoogleError } from "@/lib/cyrus/bridge/flow";
 52	import {
 53	  cyrusGoogleConfigured,
 54	  googleClientAuthorizeUrl,
 55	  googleClientForHost,
 56	  pkceChallenge,
 57	  type GoogleClient,
 58	  type GoogleProfile,
 59	} from "@/lib/google-oauth";
 60	
 61	type Env = Record<string, string | undefined>;
 62	const STATE_PURPOSE = "google:cyrus";
 63	export const GOOGLE_STATE_TTL_S = 600;
 64	
 65	export type GoogleState = { s: string; n: string; v: string; next: string };
 66	
 67	/** The state cookie's name (host-only `__Host-` in production, like the other Cyrus cookies). */
 68	export const googleStateCookie = (env: Env = process.env) => `${env.NODE_ENV === "production" ? "__Host-" : ""}cyrus_google_state`;
 69	
 70	/** The Cyrus client for this deployment, or null (flag off / not configured / mode off). */
 71	export function cyrusGoogleClient(env: Env = process.env): GoogleClient | null {
 72	  if (!cyrusGoogleConfigured(env)) return null;
 73	  const cfg = bridgeConfig(env);
 74	  return googleClientForHost(cfg.cyrusHosts[0], env);
 75	}
 76	
 77	export type StartPlan =
 78	  | { kind: "redirect"; url: string; cookieValue: string; ttlS: number }
 79	  | { kind: "error"; code: GoogleError };
 80	
 81	export function planGoogleStart(o: { env?: Env; nextRaw: string | null | undefined; nowMs?: number }): StartPlan {
 82	  const env = o.env ?? process.env;
 83	  const client = cyrusGoogleClient(env);
 84	  if (!client) return { kind: "error", code: "google_unavailable" };
 85	  const st: GoogleState = { s: randomToken(24), n: randomToken(24), v: randomToken(48), next: safeCyrusNext(o.nextRaw) };
 86	  return {
 87	    kind: "redirect",
 88	    url: googleClientAuthorizeUrl(client, { state: st.s, nonce: st.n, codeChallenge: pkceChallenge(st.v) }),
 89	    cookieValue: seal(STATE_PURPOSE, st, GOOGLE_STATE_TTL_S, env as never, o.nowMs),
 90	    ttlS: GOOGLE_STATE_TTL_S,
 91	  };
 92	}
 93	
 94	export type AccountLike = { id: string; role: string; suspended: boolean | null };
 95	
 96	export type CallbackDeps<U extends AccountLike> = {
 97	  exchange: (c: GoogleClient, code: string, o: { codeVerifier: string; nonce: string }) => Promise<{ accessToken?: string; sub?: string; error?: string }>;
 98	  fetchProfile: (accessToken: string) => Promise<{ profile?: GoogleProfile; error?: string }>;
 99	  /** lib/google-account findOrCreateGoogleAccount (shared with nxeon.cloud's Google login). */
100	  resolve: (p: GoogleProfile) => Promise<{ ok: true; user: U; isNewAccount: boolean } | { ok: false }>;
101	  /** modBuilderAccess: may this account use the studio now (private-beta allow-list / public launch)? */
102	  allowed: (u: U) => Promise<boolean>;
103	};
104	
105	export type CallbackResult<U> =
106	  | { kind: "fail"; code: GoogleError | "account" | "staff" | "ratelimited"; user?: U }
107	  | { kind: "ok"; user: U; isNewAccount: boolean; dest: string; allowed: boolean };
108	
109	export async function completeGoogleLogin<U extends AccountLike>(o: {
110	  env?: Env;
111	  query: URLSearchParams;
112	  cookieRaw: string | null | undefined;
113	  deps: CallbackDeps<U>;
114	  nowMs?: number;
115	}): Promise<CallbackResult<U>> {
116	  const env = o.env ?? process.env;
117	  const client = cyrusGoogleClient(env);
118	  if (!client) return { kind: "fail", code: "google_unavailable" };
119	  const st = unseal<GoogleState & { e: number }>(STATE_PURPOSE, o.cookieRaw, env as never, o.nowMs);
120	  const state = o.query.get("state") ?? "";
121	  if (!st || !state || !safeEqual(st.s, state)) return { kind: "fail", code: "google_state" };
122	  const err = o.query.get("error");
123	  if (err) return { kind: "fail", code: err === "access_denied" ? "google_cancelled" : "google_failed" };
124	  const code = o.query.get("code") ?? "";
125	  if (!code || code.length > 2048) return { kind: "fail", code: "google_failed" };
126	
127	  const tok = await o.deps.exchange(client, code, { codeVerifier: st.v, nonce: st.n });
128	  if (!tok.accessToken) return { kind: "fail", code: "google_failed" };
129	  const { profile } = await o.deps.fetchProfile(tok.accessToken);
130	  if (!profile) return { kind: "fail", code: "google_failed" };
131	  // The id_token (nonce-checked) and userinfo must describe the same Google account.
132	  if (tok.sub && tok.sub !== profile.sub) return { kind: "fail", code: "google_failed" };
133	  // Never link or create on an address Google did not verify.
134	  if (!profile.emailVerified) return { kind: "fail", code: "google_unverified" };
135	
136	  const acct = await o.deps.resolve(profile);
137	  if (!acct.ok) return { kind: "fail", code: "google_failed" };
138	  const { user } = acct;
139	  if (user.suspended) return { kind: "fail", code: "account", user };
140	  // Same rule as /auth/handoff: staff accounts sign in to Nxeon with their password, never through a social login.
141	  if (user.role !== "CUSTOMER") return { kind: "fail", code: "staff", user };
142	
143	  const dest = safeCyrusNext(st.next);
144	  // Not on the private-beta list: the sign-in page renders the beta panel for a signed-in account (never a 404). A
145	  // check error never blocks: the destination's own gate decides (same as /auth/nxeon/callback).
146	  const allowed = await o.deps.allowed(user).catch(() => true);
147	  return { kind: "ok", user, isNewAccount: acct.isNewAccount, dest, allowed };
148	}
149	
150	/** Where to send the browser after a successful login. */
151	export const googleLandingPath = (r: { dest: string; allowed: boolean }) =>
152	  r.allowed ? r.dest : `/sign-in?next=${encodeURIComponent(r.dest)}`;
153	
154	/**
155	 * HOOK (not implemented here): the Cyrus community username gate (feature/cyrus-community) runs first-run gating
156	 * after login. A signed-in account without a username is sent to its claim screen; return that path, or null to
157	 * continue to `dest`. Left as a no-op so that branch can fill it in without touching the protocol above.
158	 */
159	export function firstRunGate(_user: AccountLike, _dest: string): string | null {
160	  return null;
161	}
