163	export type { BridgeConfig };
164	import { cookies } from "next/headers";
165	import { bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";
166	import { googleStateCookie, planGoogleStart } from "@/lib/cyrus-bridge/google-login";
167	
168	export const dynamic = "force-dynamic";
169	
170	/**
171	 * cyrus.my "Continue with Google" start (public path /api/auth/google). Needs CYRUS_GOOGLE_LOGIN=1 + the Cyrus client;
172	 * otherwise back to sign-in with a fixed error. State + nonce + PKCE verifier + the validated `next` ride in ONE sealed,
173	 * httpOnly, host-only cookie; nothing sensitive is in a URL. Always runs on the canonical Cyrus origin so the cookie
174	 * and the registered redirect URI belong to the same host.
175	 */
176	export async function GET(req: Request) {
177	  const cfg = bridgeGate(req, "cyrus");
178	  if (!cfg) return notFound();
179	  const sp = new URL(req.url).searchParams;
180	  const origin = cfg.cyrusOrigin;
181	  if (limited(req, "google-start", 20)) return go(`${origin}/sign-in?error=ratelimited`);
182	  const host = (req.headers.get("host") ?? "").toLowerCase();
183	  if (host && host !== new URL(origin).host) {
184	    // www.cyrus.my etc: hop to the canonical host first (host-only cookies, one registered redirect URI)
185	    const q = sp.get("next") ? `?next=${encodeURIComponent(sp.get("next")!)}` : "";
186	    return go(`${origin}/api/auth/google${q}`);
187	  }
188	  const plan = planGoogleStart({ nextRaw: sp.get("next") });
189	  if (plan.kind === "error") return go(`${origin}/sign-in?error=${plan.code}`);
190	  (await cookies()).set(googleStateCookie(), plan.cookieValue, {
191	    httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge: plan.ttlS,
192	  });
193	  return go(plan.url);
194	}
195	import { cookies } from "next/headers";
196	import { db } from "@/lib/db";
197	import { createCyrusSession } from "@/lib/auth";
198	import { recordRequestActivity } from "@/lib/activity-request";
199	import { modBuilderAccess } from "@/lib/modbuilder/access";
200	import { googleClientExchange, googleFetchProfile } from "@/lib/google-oauth";
201	import { findOrCreateGoogleAccount } from "@/lib/google-account";
202	import { recordConversion, saveAttributionSnapshot } from "@/lib/cyrus/analytics/conversions";
203	import { CYRUS_ATTR_COOKIE, CYRUS_CONSENT_COOKIE } from "@/lib/cyrus/analytics/consent";
204	import { bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";
205	import { completeGoogleLogin, firstRunGate, googleLandingPath, googleStateCookie } from "@/lib/cyrus-bridge/google-login";
206	
207	export const dynamic = "force-dynamic";
208	
209	/**
210	 * cyrus.my Google callback (registered redirect URI https://<cyrus host>/api/auth/google/callback). The protocol is in
211	 * lib/cyrus-bridge/google-login; here: the state cookie is consumed, the session is the Cyrus-host cookie minted by
212	 * the same createCyrusSession the Nxeon-SSO callback uses, and every failure lands on /sign-in with a fixed code.
213	 */
214	export async function GET(req: Request) {
215	  const cfg = bridgeGate(req, "cyrus");
216	  if (!cfg) return notFound();
217	  const fail = (code: string) => go(`${cfg.cyrusOrigin}/sign-in?error=${encodeURIComponent(code)}`);
218	  const jar = await cookies();
219	  const name = googleStateCookie();
220	  const raw = jar.get(name)?.value;
221	  // one callback per start: a __Host- cookie is only cleared by a Secure Set-Cookie with path=/
222	  jar.set(name, "", { httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge: 0 });
223	  if (limited(req, "google-callback")) return fail("ratelimited");
224	
225	  const r = await completeGoogleLogin({
226	    query: new URL(req.url).searchParams,
227	    cookieRaw: raw,
228	    deps: {
229	      exchange: googleClientExchange,
230	      fetchProfile: googleFetchProfile,
231	      resolve: async (p) => {
232	        const a = await findOrCreateGoogleAccount(p, { headers: req.headers });
233	        return a.ok ? a : { ok: false };
234	      },
235	      allowed: async (u) => !!(await modBuilderAccess(u)),
236	    },
237	  });
238	
239	  if (r.kind === "fail") {
240	    if (r.user) await db.auditLog.create({ data: { userId: r.user.id, action: "user.login_denied", detail: `Google (cyrus.my): ${r.code}` } }).catch(() => {});
241	    return fail(r.code);
242	  }
243	  await db.auditLog.create({ data: { userId: r.user.id, action: "user.login", detail: "Google (cyrus.my)" } }).catch(() => {});
244	  await recordRequestActivity({ type: "auth.login", userId: r.user.id, label: "Signed in to Cyrus with Google (cyrus.my)", data: { method: "google-cyrus" } }, { headers: req.headers });
245	  // No Nxeon parent session exists on this path (identity came straight from Google), so the Cyrus session stands alone.
246	  await createCyrusSession(r.user.id, null);
247	  // Same r44 hand-off as the Nxeon-SSO callback (inert unless CYRUS_ATTRIBUTION / CYRUS_CONVERSIONS): a freshly created
248	  // account counts as a sign_up.
249	  {
250	    const ck = (n: string) => new RegExp(`(?:^|;\\s*)${n}=([^;]*)`).exec(req.headers.get("cookie") ?? "")?.[1] ?? null;
251	    if (await saveAttributionSnapshot(r.user.id, ck(CYRUS_CONSENT_COOKIE), ck(CYRUS_ATTR_COOKIE)).catch(() => false) && r.isNewAccount)
252	      await recordConversion({ id: "sign_up", key: r.user.id, userId: r.user.id });
253	  }
254	  const gate = firstRunGate(r.user, r.dest);
255	  return go(`${cfg.cyrusOrigin}${gate ?? googleLandingPath(r)}`);
256	}

  1	// Cyrus one-account bridge, platform side: the route handlers' shared plumbing (mode gate, rate limits, the sealed
  2	// state/consent cookies, absolute redirects). The protocol itself is lib/cyrus/bridge (seam-clean); this file is
  3	// allowed to use Nxeon (lib/auth, lib/rate-limit) because it IS the identity provider and the session issuer.
  4	import { NextResponse } from "next/server";
  5	import { cookies } from "next/headers";
  6	import { bridgeConfig, CYRUS_HOST_HEADER, ssoStateCookie, type BridgeConfig } from "@/lib/cyrus/bridge/config";
  7	import { randomToken, seal, unseal } from "@/lib/cyrus/bridge/assertion";
  8	import { checkRateLimit, claimOnce, clientIp } from "@/lib/rate-limit";
  9	import { emailVerificationError, isEmailVerified, isGrandfathered } from "@/lib/email-verification";
 10	
 11	export { claimOnce };
 12	const prod = () => process.env.NODE_ENV === "production";
 13	
 14	/** The handler's gate: mode on AND the request is on the expected side. Otherwise the route does not exist. */
 15	export function bridgeGate(req: Request, side: "cyrus" | "nxeon"): BridgeConfig | null {
 16	  const cfg = bridgeConfig();
 17	  if (!cfg.enabled) return null;
 18	  const onCyrus = req.headers.get(CYRUS_HOST_HEADER) === "1";
 19	  return (side === "cyrus") === onCyrus ? cfg : null;
 20	}
 21	export const notFound = () => new NextResponse("Not found.", { status: 404 });
 22	
 23	/** Per-IP limit for every bridge leg (handshakes are cheap to start; abuse should not be). */
 24	export function limited(req: Request, bucket: string, max = 30): boolean {
 25	  return !checkRateLimit(`cyrus-bridge:${bucket}:${clientIp(req)}`, { max, windowMs: 60_000 }).ok;
 26	}
 27	
 28	/** 302/303 to an absolute URL on one of the two configured origins, never cached, no Referer leak of codes. */
 29	export function go(url: string, status: 302 | 303 = 302): NextResponse {
 30	  const res = NextResponse.redirect(url, status);
 31	  res.headers.set("Cache-Control", "no-store");
 32	  res.headers.set("Referrer-Policy", "no-referrer");
 33	  return res;
 34	}
 35	
 36	export type SsoState = { s: string; n: string; next: string; m?: "create" };
 37	const STATE_TTL_S = 600;
 38	
 39	/** Start a handshake: fresh state + nonce sealed into a host-only, httpOnly, Lax cookie on THIS side. */
 40	export async function beginHandshake(side: "cyrus" | "nxeon", next: string, mode?: "create"): Promise<SsoState> {
 41	  const st: SsoState = { s: randomToken(24), n: randomToken(24), next, ...(mode ? { m: mode } : {}) };
 42	  (await cookies()).set(ssoStateCookie(side), seal(`state:${side}`, st, STATE_TTL_S), {
 43	    httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: STATE_TTL_S,
 44	  });
 45	  return st;
 46	}
 47	/** Read AND delete the handshake cookie (one callback per start). */
 48	export async function takeHandshake(side: "cyrus" | "nxeon"): Promise<SsoState | null> {
 49	  const jar = await cookies();
 50	  const raw = jar.get(ssoStateCookie(side))?.value;
 51	  // r49 (re-audit A-L1): a __Host- cookie can only be cleared by a Secure Set-Cookie (jar.delete sends none)
 52	  jar.set(ssoStateCookie(side), "", { httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: 0 });
 53	  return unseal<SsoState & { e: number }>(`state:${side}`, raw);
 54	}
 55	
 56	// ---- consent (Nxeon side): remembered per browser + account; a pre-account grant covers one sign-up handshake.
 57	const CONSENT_COOKIE = () => `${prod() ? "__Host-" : ""}nxeon_cyrus_consent`;
 58	type Consent = { u?: string; pre?: string };
 59	export async function hasConsent(userId: string, nonce: string): Promise<boolean> {
 60	  const c = unseal<Consent & { e: number }>("consent", (await cookies()).get(CONSENT_COOKIE())?.value);
 61	  return !!c && (c.u === userId || c.pre === nonce);
 62	}
 63	export async function grantConsent(g: { userId?: string; nonce?: string }): Promise<void> {
 64	  const ttl = g.userId ? 365 * 86_400 : 1_800;
 65	  (await cookies()).set(CONSENT_COOKIE(), seal("consent", g.userId ? { u: g.userId } : { pre: g.nonce }, ttl), {
 66	    httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: ttl,
 67	  });
 68	}
 69	/** CSRF token for the consent form, bound to the handshake nonce and the account (or "" before sign-up). */
 70	export const consentCsrf = (nonce: string, userId: string) => seal("consent-csrf", { n: nonce, u: userId }, 900);
 71	export function checkConsentCsrf(raw: string | null, nonce: string, userId: string): boolean {
 72	  const c = unseal<{ n: string; u: string; e: number }>("consent-csrf", raw);
 73	  return !!c && c.n === nonce && c.u === userId;
 74	}
 75	
 76	/** Same-origin check for state-changing POSTs (in addition to SameSite=Lax cookies). */
 77	export function sameOrigin(req: Request, origin: string): boolean {
 78	  const o = req.headers.get("origin");
 79	  return o === origin;
 80	}
 81	
 82	/**
 83	 * Verified-email rule for the bridge. STRICT by default: the account must have confirmed its email (or predate
 84	 * verification, like everywhere in Nxeon). Nxeon's own purchase gate fails open while mail deliverability is
 85	 * unproven (email_verification_enforced); CYRUS_BRIDGE_REQUIRE_VERIFIED=0 makes the bridge follow that rule instead.
 86	 */
 87	export async function bridgeEmailBlocked(user: Parameters<typeof emailVerificationError>[0]): Promise<boolean> {
 88	  if (process.env.CYRUS_BRIDGE_REQUIRE_VERIFIED === "0") return (await emailVerificationError(user)) !== null;
 89	  return !isEmailVerified(user) && !isGrandfathered(user);
 90	}
 91	
 92	/**
 93	 * After a FORM POST, continue with a plain navigation instead of a redirect: the site CSP has form-action 'self', and
 94	 * browsers apply form-action to every redirect that follows a form submission, so a 303 that ends cross-origin
 95	 * (consent -> authorize -> cyrus.my, cyrus.my logout -> Nxeon) would be blocked. `url` is always one we built.
 96	 */
 97	export function continueTo(url: string): Response {
 98	  const esc = url.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
 99	  return new Response(
100	    `<!doctype html><meta charset="utf-8"><meta name="referrer" content="no-referrer"><meta http-equiv="refresh" content="0;url=${esc}"><title>Continuing</title><p><a href="${esc}">Continue</a></p>`,
101	    { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "referrer-policy": "no-referrer" } },
102	  );
103	}
104	import { db } from "@/lib/db";
105	import { createCyrusSession } from "@/lib/auth";
106	import { recordRequestActivity } from "@/lib/activity-request";
107	import { modBuilderAccess } from "@/lib/modbuilder/access";
108	import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
109	import { recordConversion, saveAttributionSnapshot } from "@/lib/cyrus/analytics/conversions";
110	import { CYRUS_ATTR_COOKIE, CYRUS_CONSENT_COOKIE } from "@/lib/cyrus/analytics/consent";
111	import { safeEqual, verifyAssertion, publicKeyFor } from "@/lib/cyrus/bridge/assertion";
112	import { BRIDGE_ERRORS } from "@/lib/cyrus/bridge/flow";
113	import { bridgeEmailBlocked, bridgeGate, claimOnce, go, limited, notFound, takeHandshake } from "@/lib/cyrus-bridge/server";
114	
115	export const dynamic = "force-dynamic";
116	
117	/**
118	 * cyrus.my callback: our state cookie (constant-time match, consumed), then Nxeon's assertion (Ed25519, exact
119	 * iss/aud/typ, our nonce, 120 s, single-use jti). The account is matched by its stable id ONLY (never email), must
120	 * exist, not be suspended and have a verified email. Then the Cyrus-host session cookie (lib/auth createCyrusSession),
121	 * parented to the Nxeon session that vouched for it.
122	 */
123	export async function GET(req: Request) {
124	  const cfg = bridgeGate(req, "cyrus");
125	  if (!cfg) return notFound();
126	  const fail = (code: keyof typeof BRIDGE_ERRORS) => go(`${cfg.cyrusOrigin}/sign-in?error=${code}`);
127	  if (limited(req, "callback")) return fail("ratelimited");
128	  const url = new URL(req.url);
129	  const st = await takeHandshake("cyrus");
130	  const state = url.searchParams.get("state") ?? "";
131	  if (!st || !state || !safeEqual(st.s, state)) return fail("state");
