    12	export function bridgeConfig(env: Record<string, string | undefined> = process.env): BridgeConfig {
    13	  const hosts = (env.CYRUS_HOSTS ?? "cyrus.my,www.cyrus.my").split(",").map((h) => h.trim().toLowerCase()).filter(Boolean);
    14	  return {
    15	    enabled: env.CYRUS_DOMAIN_MODE === "1" && hosts.length > 0,
    16	    cyrusHosts: hosts,
    17	    cyrusOrigin: trimSlash(env.CYRUS_ORIGIN || `https://${hosts[0] ?? "cyrus.my"}`),
    18	    nxeonOrigin: trimSlash(env.APP_URL || "https://nxeon.cloud"),
    19	  };
