/** Mint the Cyrus-host session cookie for an account whose identity was just verified by the SSO callback. */
export async function createCyrusSession(userId: string, parentSessionHash: string | null) {
  const days = Math.max(1, await getSettingInt("session_length_days", 30));
  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
  const claims: JWTPayload = { sub: userId, sv: acct?.sessionVersion ?? 0, typ: "cyrus_session", aud: "cyrus" };
  if (parentSessionHash) claims.psh = parentSessionHash;
  const token = await new SignJWT(claims)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime(`${days}d`)
    .sign(secret);
  const jar = await cookies();
  jar.set(cyrusSessionCookie(), token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    maxAge: 60 * 60 * 24 * days,
    path: "/",
  });
  await trackSession(userId, token);
}

