11	/** server.version_changed: the mods on that server built for another version line are marked OUTDATED for their creator
12	 *  (CyrusCreatorAlert SERVERS_AHEAD, the same row the compat watch keeps, so the two never duplicate). */
13	export async function onServerVersionChanged(e: PlatformEventIn): Promise<{ outdated: number }> {
14	  const serverId = str(e, "serverId"), to = str(e, "to");
15	  if (!serverId || !to) return { outdated: 0 };
16	  const [{ lifecycleForServer }, { versionLine }] = await Promise.all([import("../lifecycle/server"), import("../lifecycle/compat")]);
17	  const rows = await lifecycleForServer(serverId).catch(() => []);
18	  let n = 0;
19	  for (const r of rows) {
20	    // the lifecycle view already compares the server's (new) version with the build's: "outdated" = game ahead / newer build
21	    if (r.view.state !== "outdated") continue;
22	    const root = await db.modBuild.findUnique({ where: { id: r.rootBuildId }, select: { userId: true } });
23	    if (!root) continue;
24	    const key = `SERVERS_AHEAD:minecraft:${versionLine(to)}`;
25	    await db.cyrusCreatorAlert.upsert({
26	      where: { rootBuildId_key: { rootBuildId: r.rootBuildId, key } },
27	      create: { userId: root.userId, rootBuildId: r.rootBuildId, kind: "SERVERS_AHEAD", key, gameId: "minecraft", targetVersion: to, buildable: false, title: `${r.name}: a server moved to Minecraft ${to}`, body: `A server running ${r.name} was updated to Minecraft ${to}. Rebuild the mod for ${versionLine(to)} so it keeps working there.`, servers: 1 },
28	      update: { lastSeenAt: new Date(), resolvedAt: null },
29	    });
30	    n++;
31	  }
32	  return { outdated: n };
33	}
