37	/** r41: Nxeon money events -> free server tokens (grants.ts: idempotent per server + period, capped, best effort). */
38	export const serverTokenHandlers: PlatformEventHandlers = {
39	  "server.purchased": async (e) => {
40	    const serverId = str(e, "serverId"), cents = num(e, "chargeCents"), term = num(e, "termMonths");
41	    if (!serverId || !e.subject || cents === null || term === null) return { granted: 0 };
42	    const r = await (await import("../tokens/grants")).grantForGameServerPurchase({ userId: e.subject, serverId, gameFamily: str(e, "gameFamily"), chargeCents: cents, termMonths: term });
43	    return { granted: r?.created ? r.amount : 0 };
44	  },
45	  "server.renewed": async (e) => {
46	    const serverId = str(e, "serverId"), cents = num(e, "netCents"), months = num(e, "months"), ps = str(e, "periodStart");
47	    const periodStart = ps ? new Date(ps) : null;
48	    if (!serverId || !e.subject || cents === null || months === null || !periodStart || Number.isNaN(periodStart.getTime())) return { granted: 0 };
49	    const r = await (await import("../tokens/grants")).grantForGameServerRenewal({ userId: e.subject, serverId, gameFamily: str(e, "gameFamily"), netCents: cents, months, periodStart });
50	    return { granted: r?.created ? r.amount : 0 };
51	  },
52	  "server.refunded": async (e) => {
53	    const serverId = str(e, "serverId");
54	    if (!serverId || !e.subject) return { revoked: 0 };
55	    return (await import("../tokens/grants")).reverseServerGrants({ userId: e.subject, serverId, reason: "refund", ref: str(e, "ref") });
56	  },
57	};
