59	export function platformEventHandlers(): PlatformEventHandlers {
60	  return {
61	    "entitlement.changed": async (e) => (await import("../tokens/entitlement")).applyEntitlement(e.data),
62	    "server.version_changed": onServerVersionChanged,
63	    // the server is gone: Cyrus' managed-plugin references to it go too (nothing left to hold them)
64	    "server.deleted": async (e) => {
65	      const serverId = str(e, "serverId");
66	      if (!serverId) return { removed: 0 };
67	      if (e.subject) revoked.set(`${serverId}:${e.subject}`, Date.now());
68	      // r41: deleted soon after deploy = that server's unspent free tokens go back (inside the clawback window only)
69	      if (e.subject) await (await import("../tokens/grants")).reverseServerGrants({ userId: e.subject, serverId, reason: "deleted", ref: "deleted" }).catch(() => undefined);
70	      return { removed: (await db.cyrusServerManagedPlugin.deleteMany({ where: { serverId } })).count };
71	    },
72	    "grant.revoked": async (e) => { const s = str(e, "serverId"); if (s && e.subject) revoked.set(`${s}:${e.subject}`, Date.now()); return { ok: true }; },
73	    "grant.created": async (e) => { const s = str(e, "serverId"); if (s && e.subject) revoked.delete(`${s}:${e.subject}`); return { ok: true }; },
74	    "grant.updated": async () => ({ ok: true }),
75	    "server.restarted": async () => ({ ok: true }),
76	    ...serverTokenHandlers,
77	  };
78	}

