/**
 * Hand a server to another account. Moves the Server row and the per-server
 * resources that are billed/managed by the owner (volumes, websites, DBs,
 * apps, cron, SSL). History (invoices, past jobs, builds, migrations, abuse
 * alerts) deliberately stays with the account it happened to. Optionally
 * rotates the root password so the previous owner's access ends.
 */
export async function customerTransferServer(serverId: string, targetEmail: string, reason: string, opts: { notify: boolean; email: boolean; resetPassword: boolean }, confirm: string): Promise<Ok<{ message: string }>> {
  const admin = await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const s = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, userId: true, status: true, user: { select: { email: true } } } });
  if (!s) return { ok: false, error: "Server not found." };
  if (confirm.trim() !== s.hostname) return { ok: false, error: `Type the hostname (${s.hostname}) to confirm.` };
  const email = String(targetEmail ?? "").trim().toLowerCase();
  const target = await db.user.findFirst({ where: { email: { equals: email, mode: "insensitive" } }, select: { id: true, email: true, suspended: true } });
  if (!target) return { ok: false, error: "No account with that email." };
  if (target.id === s.userId) return { ok: false, error: "That account already owns this server." };
  if (target.suspended) return { ok: false, error: "The target account is suspended." };
  if (["DELETING", "PROVISIONING", "REINSTALLING"].includes(s.status)) return { ok: false, error: `Server is ${s.status} — wait until it settles.` };
  if (await inflightCount(serverId)) return { ok: false, error: "A job is in flight on this server." };
  const moved = await db.$transaction(async (tx) => {
    const counts: Record<string, number> = {};
    await tx.server.update({ where: { id: serverId }, data: { userId: target.id, projectId: null } });
    counts.volumes = (await tx.volume.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.websites = (await tx.website.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.databases = (await tx.vpsDatabase.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.apps = (await tx.appInstall.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.cron = (await tx.cronJob.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.ssl = (await tx.sslCertificate.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    return counts;
  });
  if (opts.resetPassword) await db.job.create({ data: { type: "PASSWORD_RESET", serverId } });
  await recordAudit(admin.id, "adminops.transfer_server", `${s.hostname} ${s.user.email} -> ${target.email} moved=${JSON.stringify(moved)} pwReset=${!!opts.resetPassword} reason="${why}"`);
  await maybeNotify(target.id, opts.notify, opts.email, `${s.hostname} was added to your account`, `The server ${s.hostname} has been transferred to your account. ${why}`, `/dashboard/servers/${serverId}`);
  await maybeNotify(s.userId, opts.notify, false, `${s.hostname} was transferred`, `The server ${s.hostname} has been moved to another account at your request.`, "/dashboard");
  revalidateServer(serverId);
  return { ok: true, message: `Transferred to ${target.email}.` };
}
