 15	export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
 16	  const o = await ownedBuild((await params).id);
 17	  if (!o) return NOT_FOUND();
 18	  const body = (await req.json().catch(() => ({}))) as { serverId?: string; restart?: boolean; acceptCapabilities?: string };
 19	  const serverId = String(body.serverId || "");
 20	  if (!serverId) return NextResponse.json({ error: "Choose a server to install on." }, { status: 400 });
 21	  const rl = checkRateLimit(`mb:install:${o.user.id}`, { max: 10, windowMs: 60_000 });
 22	  if (!rl.ok) return NextResponse.json({ error: `Too many requests. Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
 23	
 24	  // Networking mods: platform switch on + explicit consent bound to the manifest hash.
 25	  const gate = capabilityGate({
 26	    capabilities: (o.build.result as { capabilities?: unknown } | null)?.capabilities ?? null,
 27	    networkingEnabled: await getSettingBool("cyrus_mod_networking_enabled"),
 28	    acceptedSha256: typeof body.acceptCapabilities === "string" ? body.acceptCapabilities : null,
 29	  });
 30	  if (!gate.ok) return NextResponse.json({ error: gate.error, code: gate.code }, { status: gate.status });
 31	  // Cyrus lifecycle: the same install plan the dialog showed: blockers refuse, every warning
 32	  // (version mismatch, legacy version, safety notes) must be acknowledged in `acked`.
 33	  const acked = Array.isArray((body as { acked?: unknown }).acked) ? ((body as { acked: unknown[] }).acked.filter((a) => typeof a === "string") as string[]).slice(0, 20) : [];
 34	  const sp = (await installPlansFor(o.build, o.user.id)).plans.find((p) => p.server.id === serverId);
 35	  if (sp) {
 36	    const c = confirmPlan(sp.plan, acked);
 37	    if (!c.ok) return NextResponse.json({ error: c.error, plan: sp.plan }, { status: 409 });
 38	  }
 39	
 40	  const r = await installBuildToServer(o.build, o.user.id, serverId);
 41	  if (!r.ok) return NextResponse.json({ error: r.error }, { status: 400 });
 42	
 43	  let restarted = false;
 44	  let restartNote: string | null = null;
 45	  if (body.restart && r.queued) {
 46	    restartNote = "The install is still queued on the server. Restart from the Mods tab once it shows as installed.";
 47	  } else if (body.restart) {
 48	    const p = await gamePower(serverId, "restart");
 49	    restarted = p.ok;
 50	    if (!p.ok) restartNote = p.error;
 51	  }
 52	  const lastInstall = { serverId, serverName: r.serverName, at: new Date().toISOString(), replaced: r.replaced, backupDir: r.backupDir, restarted };
 53	  await cyrusDb.modBuild.update({ where: { id: o.build.id }, data: { lastInstall } });
