  2	//
  3	// Since 2026-10-07 (Cyrus mods) this goes THROUGH THE MODS ENGINE instead of a
  4	// direct copy: the build's chain gets a GameMod row (source "cyrus",
  5	// lib/cyrus-mods/registry.ts), the ServerMod row is queued INSTALLING/UPDATING
  6	// with targetVersionId = this build, and the worker's GAME_MOD_SYNC places the
  7	// jar with lib/mods/engine.ts (state file, backup, staged write, rollback). So
  8	// the Mods tab lists it, can switch it off/on, update it, roll it back and
  9	// uninstall it like any other plugin.
 10	//
 11	// A jar a PRE-ENGINE builder install left in plugins/ (not in the engine's state
 12	// file) is backed up to /root/.nxeon-mods/backups/<stamp>-cyrus-adopt-<name>/
 13	// and removed first, so the server never loads two copies of one plugin.
 14	// The route then waits briefly for the job so the Cyrus UI can say "done".
 15	import { flightBlocks } from "../cyrus/testflight/gate";
 16	import type { ModBuild } from "@prisma/client";
 17	import { enqueueModOp } from "../mods/queue";
 18	import { loadState, ownerOf } from "../mods/engine";
 19	import { ensureCyrusGameMod, loadChain, rootOf } from "../cyrus-mods/registry";
 20	import { syncCyrusModPage } from "../cyrus-mods/pages";
 21	import { db } from "../db";
 22	import { SANDBOX } from "../sandbox";
 23	import { familyFor } from "../game-config";
 24	import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../mods/guest-fs";
 25	import { SshGuestFs } from "../../worker/mods-guest-ssh";
 26	import { cyrusConfig } from "../cyrus/config";
 27	
 28	const MC_BASE = cyrusConfig().guest.mcBase;
 29	const PLUGINS = `${MC_BASE}/plugins`;
 30	const BACKUPS = cyrusConfig().guest.modsBackupDir;
 31	/** Generated plugins target the Paper API (Adventure etc.), so Spigot/Bukkit can't load them, and they aren't Folia-safe. */
 32	export const MB_INSTALL_VARIANTS = ["paper", "purpur"];
 33	
 34	import type { MbServer } from "../cyrus/builder/types";
 35	export type { MbServer };
