 71	/**
 72	 * Move aside jars an older (pre-engine) builder install left in plugins/: only
 73	 * files the engine's state file does NOT own, named like this plugin. Backed up
 74	 * first. Returns what was moved.
 75	 */
 76	async function adoptLegacyJars(server: Parameters<typeof SshGuestFs.open>[0] & { id: string; gameVariant: string | null }, chain: ModBuild[]): Promise<{ moved: string[]; backupDir: string | null }> {
 77	  let fs: GuestFs;
 78	  let ssh: SshGuestFs | null = null;
 79	  try {
 80	    if (SANDBOX) {
 81	      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
 82	      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
 83	      fs = local;
 84	    } else {
 85	      ssh = await SshGuestFs.open(server);
 86	      fs = ssh;
 87	    }
 88	    if (!(await fs.stat(PLUGINS))) return { moved: [], backupDir: null };
 89	    const state = await loadState(fs, "minecraft");
 90	    const names = new Set(chain.map((b) => (b.pluginName ?? "").toLowerCase()).filter(Boolean));
 91	    const jars = new Set(chain.map((b) => (b.jarName ?? "").toLowerCase()).filter(Boolean));
 92	    const legacy = (await fs.list(PLUGINS)).filter((f) => {
 93	      const l = f.toLowerCase();
 94	      if (!l.endsWith(".jar") || ownerOf(state, `${PLUGINS}/${f}`)) return false;
 95	      return jars.has(l) || [...names].some((n) => l === `${n}.jar` || (l.startsWith(`${n}-`) && /^[0-9]/.test(l.slice(n.length + 1))));
 96	    });
 97	    if (!legacy.length) return { moved: [], backupDir: null };
 98	    const label = (chain[0].pluginName ?? "plugin").replace(/[^A-Za-z0-9_]/g, "") || "plugin";
 99	    const backupDir = `${BACKUPS}/${stamp()}-cyrus-adopt-${label}`;
100	    for (const f of legacy) await fs.copy(`${PLUGINS}/${f}`, `${backupDir}${PLUGINS}/${f}`);
101	    for (const f of legacy) await fs.remove(`${PLUGINS}/${f}`);
102	    return { moved: legacy, backupDir };
103	  } finally {
104	    ssh?.close();
105	  }
106	}
