110	/** The checks every install path shares (installBuildToServer and the Cyrus delivery enqueue, lib/modbuilder/delivery.ts). */
111	export async function installEligibility(build: ModBuild, userId: string, serverId: string, opts: { allowPublic?: boolean } = {}) {
112	  // allowPublic (Cyrus lifecycle): install a PUBLISHED version of another creator's mod from NxLabs.
113	  const own = build.userId === userId;
114	  if (!own && !(opts.allowPublic && (await (await import("../cyrus/lifecycle/server")).publicInstallAllowed(build, userId)))) return { ok: false as const, error: "Not found." };
115	  if (build.status !== "succeeded" || !build.jarName || !build.pluginName) return { ok: false as const, error: "This build has no plugin file to install." };
116	  const fb = flightBlocks((build.cyrus as { testFlight?: unknown } | null)?.testFlight); // Cyrus R5 optional gate
117	  if (fb.blocked) return { ok: false as const, error: fb.reason };
118	  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
119	  if (!server || server.userId !== userId) return { ok: false as const, error: "Server not found." };
120	  const servers = await modBuilderServers(userId);
121	  const facts = servers.find((s) => s.id === serverId);
122	  if (!facts) return { ok: false as const, error: "That server isn't a Minecraft server." };
123	  if (!facts.compatible) return { ok: false as const, error: facts.reason || "That server can't take this plugin." };
124	  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { ok: false as const, error: "One-click mod changes are paused right now, so nothing was installed." };
125	  return { ok: true as const, own, server, facts };
126	}
127	
128	export async function installBuildToServer(build: ModBuild, userId: string, serverId: string, opts: { waitMs?: number; allowPublic?: boolean } = {}): Promise<InstallResult> {
129	  const el = await installEligibility(build, userId, serverId, opts);
130	  if (!el.ok) return el;
131	  const { own, server, facts } = el;
132	
133	  const root = rootOf(build);
134	  const chain = await loadChain(root);
135	  await syncCyrusModPage(root);
136	  const gm = await ensureCyrusGameMod(root, chain);
137	  if (!gm) return { ok: false, error: "This build has no plugin file to install." };
138	
139	  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
140	  if (existing?.status === "DISABLED") return { ok: false, error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first, then install this version.` };
141	  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { ok: false, error: `${gm.name} is busy on that server (${existing.status.toLowerCase()}). Try again in a moment.` };
142	  if (existing?.status === "INSTALLED" && existing.versionId === build.id) {
143	    return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: [], backupDir: null, serverName: facts.name, queued: false, jobId: "", modId: gm.id };
144	  }
145	  const op = existing?.status === "INSTALLED" ? "update" : "install";
146	
147	  // First engine install on a server an older builder install already used: adopt its jar.
148	  let adopted: { moved: string[]; backupDir: string | null } = { moved: [], backupDir: null };
149	  const touched = own && chain.some((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
150	  if (op === "install" && touched) {
151	    try {
152	      adopted = await adoptLegacyJars(server, chain);
153	    } catch (e) {
154	      console.error("[modbuilder] legacy adopt failed", build.id, serverId, (e as Error).message);
155	      return { ok: false, error: "We couldn't reach the server to check its plugins folder. Check it's online and try again." };
156	    }
157	  }
158	
159	  const prevVersion = existing?.status === "INSTALLED" ? existing.version : null;
160	  const q = await enqueueModOp(serverId, gm.id, op, { userId, slug: gm.slug }, { targetVersionId: build.id });
161	  if (!q.ok) return { ok: false, error: q.error };
162	
163	  // Wait (briefly) for the worker so the builder UI can report the outcome.
164	  const deadline = Date.now() + (opts.waitMs ?? 45_000);
165	  while (Date.now() < deadline) {
166	    await sleep(1000);
167	    const job = await db.job.findUnique({ where: { id: q.jobId }, select: { status: true, error: true } });
168	    if (!job || job.status === "QUEUED" || job.status === "RUNNING") continue;
169	    const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
170	    if (job.status === "FAILED") return { ok: false, error: sm?.error || "The install job failed. Check the server's Mods tab." };
171	    if (!sm || sm.status === "FAILED" || sm.versionId !== build.id) return { ok: false, error: sm?.error || "The plugin wasn't installed. Check the server's Mods tab." };
172	    return {
173	      ok: true,
174	      path: `${PLUGINS}/${build.jarName}`,
175	      replaced: [...adopted.moved, ...(prevVersion ? [`${gm.name} ${prevVersion}`] : [])],
176	      backupDir: adopted.backupDir,
177	      serverName: facts.name,
178	      queued: false,
179	      jobId: q.jobId,
180	      modId: gm.id,
181	    };
182	  }
183	  return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: adopted.moved, backupDir: adopted.backupDir, serverName: facts.name, queued: true, jobId: q.jobId, modId: gm.id };
184	}

     1	// Cyrus game slots (D-63): how many GAMES an account may mod, per plan. PURE + client-safe; unit-tested in
     2	// test/cyrus-game-slots.test.ts. The server half (usage from the DB, the race-safe claim) is ./game-slots.server.ts.
     3	//
     4	// RULES
     5	//   slots        a plan has `games` slots (setting cyrus_tok_plan_<tier>_games; 0 = UNLIMITED). PLACEHOLDER defaults:
     6	//                Free 1, Katara 1, Saka 3, All models unlimited.
     7	//   in use       a game the account actually mods: it has at least one project or build in that game that is not
     8	//                archived. The FIRST project in a new game takes a slot; the slot frees when every project in that game
     9	//                is archived or deleted. Builds, changes, installs and exports inside a game already in use never ask.
    10	//   enforcement  SERVER SIDE at every creation path (new build, change on an archived project, designer build, remix,
    11	//                import, API v1 createProject / createBuild): plan / money gating, so it is HARD (D-62 keeps money hard),
    12	//                with a plain message and the upgrade path. Off when the account is outside the token economy or
    13	//                cyrus_tok_enforce is false (exactly like the model unlock), so preview / pre-launch behaviour is unchanged.
    14	//   override     an admin can set an account's slots (JSON setting cyrus_game_slot_overrides, like cyrus_suspensions);
    15	//                an override REPLACES the plan's number while it runs (it can raise or lower it), 0 = unlimited.
    16	import type { TokenConfig, TokenTier } from "./config-pure";
    17	
    18	export const UNLIMITED = 0;
    19	export const GAME_SLOTS_FULL = "game_slots_full";
    20	export const GAME_SLOT_OVERRIDES_KEY = "cyrus_game_slot_overrides";
    21	
    22	/** The plan's slots (0 = unlimited). */
    23	export const planGames = (tier: TokenTier, cfg: Pick<TokenConfig, "plan">): number => cfg.plan.games[tier] ?? 1;
    24	
    25	export type GameSlotOverride = { userId: string; games: number; note: string; by: string; at: string; until: string | null };
    26	
    27	/** Parse the stored JSON list (never throws; bad entries are dropped; one entry per account, the last wins). */
    28	export function parseGameSlotOverrides(raw: string | null | undefined): GameSlotOverride[] {
    29	  let v: unknown;
    30	  try { v = JSON.parse(raw || "[]"); } catch { return []; }
    31	  if (!Array.isArray(v)) return [];
    32	  const byUser = new Map<string, GameSlotOverride>();
    33	  for (const x of v) {
    34	    if (!x || typeof x !== "object") continue;
    35	    const r = x as Record<string, unknown>;
    36	    if (typeof r.userId !== "string" || !/^[A-Za-z0-9_-]{1,64}$/.test(r.userId)) continue;
    37	    const g = Number(r.games);
    38	    if (!Number.isInteger(g) || g < 0 || g > 1000) continue;
    39	    byUser.set(r.userId, {
    40	      userId: r.userId, games: g, note: String(r.note ?? "").slice(0, 300), by: String(r.by ?? "").slice(0, 64),
    41	      at: typeof r.at === "string" ? r.at : new Date(0).toISOString(),
    42	      until: typeof r.until === "string" && !Number.isNaN(Date.parse(r.until)) ? r.until : null,
    43	    });
    44	  }
    45	  return [...byUser.values()];
    46	}
    47	
    48	export const activeGameSlotOverride = (list: GameSlotOverride[], userId: string, now: Date): GameSlotOverride | null =>
    49	  list.find((o) => o.userId === userId && (!o.until || Date.parse(o.until) > now.getTime())) ?? null;
    50	export const upsertGameSlotOverride = (list: GameSlotOverride[], o: GameSlotOverride): GameSlotOverride[] => [...list.filter((x) => x.userId !== o.userId), o];
    51	export const removeGameSlotOverride = (list: GameSlotOverride[], userId: string): GameSlotOverride[] => list.filter((x) => x.userId !== userId);
    52	export const pruneGameSlotOverrides = (list: GameSlotOverride[], now: Date): GameSlotOverride[] => list.filter((o) => !o.until || Date.parse(o.until) > now.getTime());
    53	
    54	/** The account's slots right now: an active override replaces the plan's number. */
    55	export function gamesLimit(tier: TokenTier, cfg: Pick<TokenConfig, "plan">, override: GameSlotOverride | null): number {
    56	  return override ? override.games : planGames(tier, cfg);
    57	}
    58	
    59	export type GameUsageRow = { game: string; archived: boolean };
    60	
    61	/** Distinct games with at least one project/build that is not archived, in first-seen order. */
    62	export function gamesInUse(rows: readonly GameUsageRow[]): string[] {
    63	  const out: string[] = [];
    64	  for (const r of rows) if (!r.archived && r.game && !out.includes(r.game)) out.push(r.game);
    65	  return out;
    66	}
    67	
    68	export type GameSlotDecision =
    69	  | { ok: true; takesSlot: boolean; used: number; limit: number }
    70	  | { ok: false; code: typeof GAME_SLOTS_FULL; used: number; limit: number; inUse: string[]; error: string; upgrade: TokenTier | null };
    71	
    72	/** The cheapest plan whose slots would fit one more game (null = none; then only an admin override helps). */
    73	export function upgradeTierFor(usedCount: number, cfg: Pick<TokenConfig, "plan">, from: TokenTier): TokenTier | null {
    74	  const order: TokenTier[] = ["free", "katara", "saka", "all"];
    75	  for (const t of order.slice(order.indexOf(from) + 1)) {
    76	    const g = planGames(t, cfg);
    77	    if (g === UNLIMITED || g > usedCount) return t;
    78	  }
    79	  return null;
    80	}
