async function createBankBuild(user: User, i: { prompt: string; mcVersion: string; want: string }): Promise<CreateBuildResult> {
  const m = matchBank(i.prompt, { mcVersion: i.mcVersion });
  if (!m || m.id !== i.want) return fail(409, { error: "This request no longer matches the ready-made mod. Build it with the AI instead.", code: "bank_mismatch" });
  const served = (await serviceBankEntries()).get(m.id);
  if (!served || (served.length && !served.includes(i.mcVersion))) return fail(409, { error: "The ready-made version of this mod is not available right now. Build it with the AI instead.", code: "bank_unavailable" });
  const id = "mb" + randomBytes(10).toString("hex");
  const gate = await gateBuild({ user, buildId: id, requested: undefined, baseModel: undefined, text: i.prompt, bank: true });
  if (!gate.ok) return fail(gate.status, { error: gate.error, code: gate.code, need: gate.need, available: gate.available, model: gate.model });
  const cyrus: CyrusMeta = { ...(gate.model ? { model: gate.model } : {}), bank: { id: m.id, version: m.version, via: m.via } };
  await cyrusDb.modBuild.create({ data: { id, userId: user.id, prompt: i.prompt, changeRequest: null, baseBuildId: null, rootBuildId: id, mcVersion: i.mcVersion, pluginName: null, cyrus } });
  try {
    await svcCreate({ id, prompt: i.prompt, mcVersion: i.mcVersion, bank: { id: m.id, params: m.params }, priority: "interactive", account: accountKey(user.id) });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    const busy = e instanceof ModBuilderBusy ? busyFailure(e) : null;
    await cyrusDb.modBuild.update({ where: { id }, data: { status: "failed", errorCode: busy ? busy.errorCode : "unavailable", error: busy ? busy.error : msg, finishedAt: new Date() } });
    if (gate.tracked) await releaseBuildTokens(id);
    console.error("[modbuilder] bank create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.build", detail: `${id} bank:${m.id}` } }).catch(() => {});
  const fresh = await cyrusDb.modBuild.findUnique({ where: { id } });
  return { ok: true, status: 201, build: toView(fresh!), reserved: gate.reserved };
}


/** Create a project and reserve its unique namespace. A namespace clash (another project holds it) retries with a new seed. */
export async function createProject(input: CreateProjectInput, opts: CreateProjectOptions = {}): Promise<CyrusProject> {
  if (!input.userId) throw new EngineStoreError("bad_input", "userId is required");
  if (!GAME_ID_RE.test(input.game) || !getAdapter(input.game)) throw new EngineStoreError("unknown_game", `no game adapter for "${input.game}"`);
  const id = "cp" + randomBytes(10).toString("hex");
  const nsFor = opts.namespaceFor ?? ((pid: string, n: number) => namespaceFromSeed(n === 0 ? pid : `${pid}:${n}`));
  const max = opts.maxAttempts ?? 8;
  for (let attempt = 0; attempt < max; attempt++) {
    const namespace = nsFor(id, attempt);
    try {
      return await db.cyrusProject.create({
        data: { id, userId: input.userId, game: input.game, namespace, title: input.title ?? null, rootBuildId: input.rootBuildId ?? null },
      });
    } catch (e) {
      if (isUniqueViolation(e, "namespace")) continue;
      if (isUniqueViolation(e, "rootBuildId")) throw new EngineStoreError("root_taken", "that build chain already has a project");
      throw e;
    }
  }
  throw new EngineStoreError("namespace_exhausted", `could not reserve a free namespace in ${max} attempts`);
}

/**
 * D-63: create a project the CUSTOMER asked for (API v1 createProject, import): the first project in a game the account
 * does not mod yet needs a free game slot, claimed race-safely (lib/cyrus/tokens/game-slots.server.ts). Refused =
 * EngineStoreError("game_slots_full" | "game_slots_unknown") with the customer message. Internal callers that attach a
 * project to an EXISTING build chain (asset sync, config studio) keep using createProject: that game is already in use.
 */
export async function createCustomerProject(input: CreateProjectInput, opts: CreateProjectOptions = {}): Promise<CyrusProject> {
  if (!input.userId) throw new EngineStoreError("bad_input", "userId is required");
  if (!GAME_ID_RE.test(input.game) || !getAdapter(input.game)) throw new EngineStoreError("unknown_game", `no game adapter for "${input.game}"`);
  const { withGameSlot } = await import("../tokens/game-slots.server");
  const id = "cp" + randomBytes(10).toString("hex");
  const nsFor = opts.namespaceFor ?? ((pid: string, n: number) => namespaceFromSeed(n === 0 ? pid : `${pid}:${n}`));
  const max = opts.maxAttempts ?? 8;
  for (let attempt = 0; attempt < max; attempt++) {
    const namespace = nsFor(id, attempt);
    try {
      const r = await withGameSlot({ id: input.userId }, input.game, (c) => c.cyrusProject.create({
        data: { id, userId: input.userId, game: input.game, namespace, title: input.title ?? null, rootBuildId: input.rootBuildId ?? null },
      }));
      if (!r.ok) throw new EngineStoreError(r.code, r.error);
      return r.value;
    } catch (e) {
      if (isUniqueViolation(e, "namespace")) continue;
      if (isUniqueViolation(e, "rootBuildId")) throw new EngineStoreError("root_taken", "that build chain already has a project");
      throw e;
    }
  }
  throw new EngineStoreError("namespace_exhausted", `could not reserve a free namespace in ${max} attempts`);
}

