const DAY = 86_400_000;
export const initialKey = (serverId: string) => `gs:${serverId}:initial`;
export const renewalKey = (serverId: string, periodStart: Date) => `gs:${serverId}:renew:${periodStart.toISOString()}`;

type GrantCtx = { userId: string; serverId: string; gameFamily?: string | null };

async function eligible(c: GrantCtx): Promise<boolean> {
  const cfg = await loadTokenConfig();
  // r41 scope (PLACEHOLDER setting cyrus_tok_grant_scope): cyrus_games = servers of a game Cyrus builds for (registry
  // status "live", the pre-r41 rule); all_game_servers = any game server; all_servers = any paid Nxeon server.
  if (cfg.grant.scope !== "all_servers") {
    const fam = c.gameFamily ?? await getHost().servers.planFamily(c.serverId);
    if (cfg.grant.scope === "cyrus_games" ? !earnsCyrusTokens(fam) : !fam) return false;
  }
  return tokensActiveForUserId(c.userId, cfg);
}

/** Tokens this server has ever been granted (gross: a reversal does not make room again), for the per-server lifetime cap. */
async function serverLifetime(tx: Tx, serverId: string) {
  const a = await tx.cyrusTokenLedger.aggregate({ where: { sourceRef: serverId, source: { in: ["server_initial", "server_renewal"] }, kind: "grant" }, _sum: { delta: true } });
  return a._sum.delta ?? 0;
}

/** Apply the per-server lifetime cap and the per-account held cap (in that order). */
async function capServerGrant(tx: Tx, userId: string, serverId: string, amount: number, at: Date, cfg: Awaited<ReturnType<typeof loadTokenConfig>>) {
  let note: string | undefined;
  if (cfg.grant.perServerCap > 0) {
    const room = Math.max(0, cfg.grant.perServerCap - (await serverLifetime(tx, serverId)));
    if (amount > room) { amount = room; note = `capped at ${cfg.grant.perServerCap} tokens per server`; }
  }
  const held = await serverGrantBalance(tx, userId, at);
  const room = Math.max(0, cfg.grant.balanceCap - held);
  if (amount > room) { amount = room; note = `capped at ${cfg.grant.balanceCap} server tokens held`; }
  return { amount, note };
}

/** Server-grant tokens the account still holds, for the per-account cap. */
async function serverGrantBalance(tx: Tx, userId: string, now: Date) {
  const a = await tx.cyrusTokenLot.aggregate({
    where: { userId, source: { in: ["server_initial", "server_renewal"] }, remaining: { gt: 0 }, OR: [{ expiresAt: null }, { expiresAt: { gt: now } }] },
    _sum: { remaining: true },
  });
  return a._sum.remaining ?? 0;
}

/**
 * Purchase grant. `chargeCents` is what the order actually charged for `termMonths`
 * (after coupons/partner discounts, pre-tax); a $0 order (trial) earns nothing now and
 * gets its initial grant on its first paid renewal instead.
 */
export async function grantForGameServerPurchase(c: GrantCtx & { chargeCents: number; termMonths: number; now?: Date }): Promise<CreditResult | null> {
  if (!(c.chargeCents > 0)) return null;
  if (!(await eligible(c))) return null;
  const cfg = await loadTokenConfig();
  const term = Math.max(1, Math.round(c.termMonths || 1));
  const monthlyCents = Math.round(c.chargeCents / term);
  const g = serverGrant("initial", monthlyCents, term, cfg);
  if (!g.tokens) return null;
  const now = c.now ?? new Date();
  return creditTokens({
    userId: c.userId,
    amount: g.tokens,
    kind: "grant",
    source: "server_initial",
    sourceRef: c.serverId,
    idemKey: initialKey(c.serverId),
    expiresAt: new Date(now.getTime() + g.expiresInDays * DAY),
    note: "Game server purchase",
    meta: { monthlyCents, termMonths: term, formula: { initialPerMonth: g.initialPerMonth, renewPerMonth: g.renewPerMonth, months: g.months } },
    now,
    clamp: async (tx, amount, at) => {
      // Abuse limits: a handful of initial grants per 30 days, and a ceiling on held server tokens.
      const recent = await tx.cyrusTokenLedger.count({ where: { userId: c.userId, source: "server_initial", kind: "grant", delta: { gt: 0 }, createdAt: { gt: new Date(at.getTime() - 30 * DAY) } } });
      if (recent >= cfg.grant.maxInitialPer30d) return { amount: 0, note: `capped: ${recent} server grants in 30 days` };
      return capServerGrant(tx, c.userId, c.serverId, amount, at, cfg);
    },
  });
}

/**
 * Paid-renewal grant. `netCents` = the renewal's pre-tax charge for `months`. If this server
 * never got its initial grant (bought with a $0 trial, or before tokens existed for this
 * account) the first paid renewal earns the initial amount instead.
 */
export async function grantForGameServerRenewal(c: GrantCtx & { netCents: number; months: number; periodStart: Date; now?: Date }): Promise<CreditResult | null> {
  if (!(c.netCents > 0)) return null;
  if (!(await eligible(c))) return null;
  const had = await db.cyrusTokenLedger.findUnique({ where: { idemKey: initialKey(c.serverId) }, select: { id: true } });
  if (!had) return grantForGameServerPurchase({ userId: c.userId, serverId: c.serverId, gameFamily: c.gameFamily, chargeCents: c.netCents, termMonths: c.months, now: c.now });
  const cfg = await loadTokenConfig();
  const months = Math.max(1, Math.round(c.months || 1));
  const monthlyCents = Math.round(c.netCents / months);
  const g = serverGrant("renewal", monthlyCents, months, cfg);
  if (!g.tokens) return null;
  const now = c.now ?? new Date();
  return creditTokens({
    userId: c.userId,
    amount: g.tokens,
    kind: "grant",
    source: "server_renewal",
    sourceRef: c.serverId,
    idemKey: renewalKey(c.serverId, c.periodStart),
    expiresAt: new Date(now.getTime() + g.expiresInDays * DAY),
    note: "Game server renewal",
    meta: { monthlyCents, months, periodStart: c.periodStart.toISOString() },
    now,
    clamp: (tx, amount, at) => capServerGrant(tx, c.userId, c.serverId, amount, at, cfg),
  });
}

export type ReverseReason = "refund" | "cancel" | "deleted";

/**
 * r41: take back a server's UNSPENT grant tokens (never below zero, never tokens a running build holds). `refund` and
 * `cancel` always reverse; `deleted` only within cyrus_tok_grant_clawback_days of the server's first grant (deploy and
 * delete farming). Idempotent per server + reason + ref (`gs:<serverId>:reverse:<reason>:<ref>`).
 */
export async function reverseServerGrants(c: { userId: string; serverId: string; reason: ReverseReason; ref?: string | null; now?: Date }): Promise<{ revoked: number; skipped?: string }> {
  const now = c.now ?? new Date();
  const cfg = await loadTokenConfig();
  const first = await db.cyrusTokenLedger.findUnique({ where: { idemKey: initialKey(c.serverId) }, select: { userId: true, createdAt: true } });
  if (!first || first.userId !== c.userId) return { revoked: 0, skipped: "no grant" };
  if (c.reason === "deleted" && !(cfg.grant.clawbackDays > 0 && now.getTime() - first.createdAt.getTime() <= cfg.grant.clawbackDays * DAY)) return { revoked: 0, skipped: "outside clawback window" };
  const lots = await db.cyrusTokenLot.findMany({ where: { userId: c.userId, sourceRef: c.serverId, source: { in: ["server_initial", "server_renewal"] }, remaining: { gt: 0 } }, select: { id: true, remaining: true } });
  const want = lots.reduce((a, l) => a + l.remaining, 0);
  const ref = (c.ref ?? "once").replace(/[^A-Za-z0-9_:.-]/g, "").slice(0, 80) || "once";
  const r = await revokeTokens({
    userId: c.userId, amount: want, lotIds: lots.map((l) => l.id), sourceRef: c.serverId, now,
    idemKey: `gs:${c.serverId}:reverse:${c.reason}:${ref}`,
    note: c.reason === "refund" ? "Server refunded" : c.reason === "cancel" ? "Server cancelled" : "Server deleted soon after deploy",
    meta: { serverId: c.serverId, reason: c.reason },
  });
  return { revoked: r.revoked };
}

/** Wrappers for the order/renewal code paths: never throw, log instead. */
export async function safeGrantPurchase(c: Parameters<typeof grantForGameServerPurchase>[0]): Promise<void> {
  try { await grantForGameServerPurchase(c); } catch (e) { console.error("[cyrus-tokens] purchase grant failed", c.serverId, (e as Error).message); }
}
export async function safeReverseServerGrants(c: Parameters<typeof reverseServerGrants>[0]): Promise<void> {
  try { await reverseServerGrants(c); } catch (e) { console.error("[cyrus-tokens] server grant reversal failed", c.serverId, (e as Error).message); }
}
export async function safeGrantRenewal(c: Parameters<typeof grantForGameServerRenewal>[0]): Promise<void> {
  try { await grantForGameServerRenewal(c); } catch (e) { console.error("[cyrus-tokens] renewal grant failed", c.serverId, (e as Error).message); }
}

