// Cyrus R5 delivery: a copy-on-write JOURNAL over a server's file access, so a delivery can be rolled back to the
// EXACT previous bytes of every path it (or any installer it calls: the Mods engine, the managed-plugin installer, the
// Mod Pack unit, the creature writer, the Pack Loader config writer) changed.
//
// Every mutation goes through `JournalFs`. Before the FIRST mutation of a path it records what was there: a file is
// copied to the journal's backup folder (on the server: `cp`, no download) and hashed; a missing path is recorded as
// absent; a directory about to be removed is captured file by file. Parent folders a write creates are recorded too.
// `rollback()` undoes everything in reverse order (restored files are written as a new file + rename, so a running
// JVM that holds the old file open is never corrupted), then re-reads every journaled path and compares it with the
// recorded hash (or absence). `commit()` drops the backups. The journal itself is persisted next to the backups
// after every new entry, so a crashed worker leaves a recoverable journal (`recoverJournal`).
// HOST SEAM: `TxnFs` is a GuestFs-shaped subset; Nxeon's SshGuestFs / LocalGuestFs satisfy it structurally.
import { createHash, randomBytes } from "node:crypto";
import { cyrusConfig } from "../config";

export interface TxnFs {
  stat(p: string): Promise<{ type: "file" | "dir"; size: number } | null>;
  readFile(p: string, maxBytes?: number): Promise<Buffer | null>;
  writeFile(p: string, data: Buffer): Promise<void>;
  mkdirp(p: string): Promise<void>;
  rename(from: string, to: string): Promise<void>;
