/**
 * Permanently delete a customer account — the same transaction the customer's
 * own GDPR deletion runs (lib/actions-gdpr.ts deleteMyAccount), with STRICTER
 * preconditions because nobody is asking for it from the account itself:
 * no servers at all (not even DELETING), no hosting/email/domains, a zero
 * wallet, no open invoices, and typed email + the word DELETE + a reason.
 */
export async function adminDeleteAccount(userId: string, typedEmail: string, typedWord: string, reason: string, idem?: string): Promise<Ok> {
  const admin = await gate();
  const why = cleanReason(reason);
  if (!why || why.length < 10) return { ok: false, error: "Give a reason of at least 10 characters." };
  const rl = limited(admin.id, "delete_account", 3, 60 * 60_000);
  if (rl) return { ok: false, error: rl };
  const u = await customer(userId);
  if (!u) return { ok: false, error: "Customer not found." };
  if (u.role !== "CUSTOMER") return { ok: false, error: "Staff and admin accounts cannot be deleted from here." };
  if (u.id === admin.id) return { ok: false, error: "You cannot delete your own account." };
  if (typedEmail.trim().toLowerCase() !== u.email.toLowerCase() || typedWord.trim() !== "DELETE") {
    return { ok: false, error: `Type ${u.email} and the word DELETE to confirm.` };
  }
  const [servers, hosting, emailSubs, domains, openInvoices] = await Promise.all([
    db.server.count({ where: { userId: u.id } }),
    db.hostingAccount.count({ where: { userId: u.id } }),
    db.emailSubscription.count({ where: { userId: u.id } }),
    db.domain.count({ where: { userId: u.id } }),
    db.invoice.count({ where: { userId: u.id, status: "OPEN" } }),
  ]);
  const blockers: string[] = [];
  if (servers) blockers.push(`${servers} server(s) — delete them first`);
  if (hosting) blockers.push(`${hosting} hosting account(s)`);
  if (emailSubs) blockers.push(`${emailSubs} email subscription(s)`);
  if (domains) blockers.push(`${domains} domain(s)`);
  if (openInvoices) blockers.push(`${openInvoices} open invoice(s)`);
  if (u.balanceCents !== 0) blockers.push(`wallet balance is not zero — refund or adjust it first`);
  if (blockers.length) return { ok: false, error: `Cannot delete yet: ${blockers.join("; ")}.` };
  if (idem && !claimOnce(`adm360c:delete_account:${admin.id}:${idem}`, 15 * 60_000)) return { ok: false, error: "Already submitted." };

  try {
  await db.$transaction([
    db.auditLog.create({ data: { userId: admin.id, action: "admin.client.account_deleted", detail: `${u.email} (${u.id}) deleted by admin — ${why}`, category: "client", target: u.id } }),
    db.auditLog.updateMany({ where: { userId: u.id }, data: { userId: null } }),
    db.user.updateMany({ where: { referredById: u.id }, data: { referredById: null } }),
    db.walletTransaction.deleteMany({ where: { userId: u.id } }),
    db.passwordResetToken.deleteMany({ where: { userId: u.id } }),
    db.user.delete({ where: { id: u.id } }),
  ]);
  } catch (e) {
    // A relation without a cascade (some newer model) refuses the delete — the
    // transaction rolled back, nothing was removed. Say so instead of a 500.
    return { ok: false, error: `Nothing was deleted — the database refused: ${String((e as Error)?.message ?? e).split("\n").pop()?.slice(0, 200)}` };
  }
  revalidatePath("/admin/users");
  return { ok: true };
}

